"""Command line entry point: ``python3 -m seal_derive --root <dir> <subcommand>``.

Exit codes: 0 success, 1 a storage or verification error, 2 a usage error.
"""

from __future__ import annotations

import argparse
import json
import sys

from . import DOMAIN, SOURCE_CATEGORIES, __version__
from .core import KeyRing

USAGE_ERROR = 2

def _tags() -> list[str]:
    """Tags this domain claims: the comma-separated line that follows each named category heading."""
    import pathlib
    corpus = pathlib.Path(__file__).resolve().parent.parent / "corpus.md"
    if not corpus.is_file():
        return []
    wanted, tags, collect = set(SOURCE_CATEGORIES), [], False
    for line in corpus.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if stripped in wanted:
            collect = True
            continue
        if not collect or not stripped:
            continue
        for token in stripped.split(","):
            token = token.strip().replace("\\", "")
            if token and token not in tags:
                tags.append(token)
        collect = False
    return tags


def _report(component_names: list[str], readiness: dict[str, bool]) -> str:
    import json
    return json.dumps({"domain": DOMAIN, "version": __version__, "sourceCategories": list(SOURCE_CATEGORIES),
                       "tags": _tags(), "components": component_names, "readiness": readiness},
                      ensure_ascii=False, sort_keys=True)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="seal_derive", description="口令派生与版本化封存")
    parser.add_argument("--root", required=True, help="working directory")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("init", help="create an empty store")
    for verb, help_text in (("load", "load material"), ("versions", "list versions"), ("active", "print the active version")):
        node = sub.add_parser(verb, help=help_text); node.add_argument("key_id"); node.add_argument("--password"); node.add_argument("--version", type=int)
    seal = sub.add_parser("seal", help="seal material under a key id")
    seal.add_argument("key_id"); seal.add_argument("material"); seal.add_argument("--password"); seal.add_argument("--iterations", type=int, default=200_000)
    for verb in ("set-active", "revoke"):
        node = sub.add_parser(verb); node.add_argument("key_id"); node.add_argument("version", type=int)
    sub.add_parser("report", help="print this domain's report as JSON")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    ring = KeyRing(args.root)
    try:
        if args.command == "init":
            ring.init(); print(f"initialised {ring.path}")
        elif args.command == "seal":
            print(ring.seal(args.key_id, args.material, args.password, args.iterations))
        elif args.command == "load":
            sys.stdout.buffer.write(ring.load(args.key_id, args.version, args.password) + b"\n")
        elif args.command == "versions":
            print(json.dumps(ring.versions(args.key_id)))
        elif args.command == "active":
            print(ring.active(args.key_id))
        elif args.command == "set-active":
            ring.set_active(args.key_id, args.version); print("ok")
        elif args.command == "revoke":
            ring.revoke(args.key_id, args.version); print("ok")
        elif args.command == "report":
            print(_report(["keyring", "derive"], {"seal": True, "rotate": True, "revoke": True, "constantTime": False}))
        return 0
    except FileNotFoundError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    except (KeyError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return USAGE_ERROR


if __name__ == "__main__":
    raise SystemExit(main())

"""Versioned sealed material, derived from a passphrase when one is given."""

from __future__ import annotations

import base64
import hashlib
import json
import secrets
from pathlib import Path

__all__ = ["KeyRing"]

RING_FILE = "keyring.json"


def _derive(password: str, salt: bytes, iterations: int, length: int = 32) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations, dklen=length)


class KeyRing:
    """A single-process key ring rooted at ``root``."""

    def __init__(self, root: str | Path) -> None:
        self.directory = Path(root)
        self.path = self.directory / RING_FILE

    def init(self) -> None:
        self.directory.mkdir(parents=True, exist_ok=True)
        self._write({"keys": {}})

    def _read(self) -> dict:
        if not self.path.is_file():
            raise FileNotFoundError(f"no key ring at {self.path}; run init first")
        return json.loads(self.path.read_text(encoding="utf-8"))

    def _write(self, document: dict) -> None:
        self.directory.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps(document, sort_keys=True, indent=2), encoding="utf-8")

    def _entry(self, document: dict, key_id: str) -> dict:
        if key_id not in document["keys"]:
            raise KeyError(f"unknown key {key_id!r}")
        return document["keys"][key_id]

    def seal(self, key_id: str, material: str, password: str | None = None, iterations: int = 200_000) -> int:
        if not key_id:
            raise ValueError("key_id must be non-empty")
        if iterations <= 0:
            raise ValueError("iterations must be positive")
        document = self._read()
        entry = document["keys"].setdefault(key_id, {"versions": [], "active": 0})
        version = (entry["versions"][-1]["version"] if entry["versions"] else 0) + 1
        salt = secrets.token_bytes(16)
        if password is None:
            record = {"version": version, "scheme": "plain", "material": base64.b64encode(material.encode("utf-8")).decode("ascii")}
        else:
            record = {"version": version, "scheme": "pbkdf2-sha256", "iterations": iterations,
                      "salt": base64.b64encode(salt).decode("ascii"),
                      "material": base64.b64encode(_derive(password, salt, iterations)).decode("ascii")}
        record["revoked"] = False
        entry["versions"].append(record)
        entry["active"] = version
        self._write(document)
        return version

    def versions(self, key_id: str) -> list[int]:
        return [int(item["version"]) for item in self._entry(self._read(), key_id)["versions"]]

    def active(self, key_id: str) -> int:
        return int(self._entry(self._read(), key_id)["active"])

    def _record(self, key_id: str, version: int | None) -> dict:
        entry = self._entry(self._read(), key_id)
        wanted = entry["active"] if version is None else int(version)
        for item in entry["versions"]:
            if int(item["version"]) == wanted:
                return item
        raise KeyError(f"unknown version {wanted} for {key_id!r}")

    def load(self, key_id: str, version: int | None = None, password: str | None = None) -> bytes:
        record = self._record(key_id, version)
        if record["revoked"]:
            raise ValueError(f"version {record['version']} of {key_id!r} is revoked")
        raw = base64.b64decode(record["material"])
        if record["scheme"] == "plain":
            return raw
        if password is None:
            raise ValueError("this version was derived from a passphrase; supply one")
        # The derived material is re-derived from the caller's passphrase and compared to the stored one.
        expected = _derive(password, base64.b64decode(record["salt"]), int(record["iterations"]), len(raw))
        if not secrets.compare_digest(expected, raw):
            raise ValueError("passphrase does not match this version")
        return raw

    def set_active(self, key_id: str, version: int) -> None:
        document = self._read()
        entry = self._entry(document, key_id)
        self._record(key_id, version)
        entry["active"] = int(version)
        self._write(document)

    def revoke(self, key_id: str, version: int) -> None:
        document = self._read()
        self._record(key_id, version)
        for item in self._entry(document, key_id)["versions"]:
            if int(item["version"]) == int(version):
                item["revoked"] = True
        self._write(document)

    def is_revoked(self, key_id: str, version: int) -> bool:
        return bool(self._record(key_id, version)["revoked"])

